const upsertPerson = `-- name: UpsertPerson :one
INSERT INTO people (source, external_id, name, native_name, image) VALUES (?, ?, ?, ?, ?)
ON CONFLICT (source, external_id) DO UPDATE SET
    name = excluded.name,
    native_name = CASE WHEN excluded.native_name != '' THEN excluded.native_name ELSE people.native_name END,
    image = CASE WHEN excluded.image != '' THEN excluded.image ELSE people.image END
RETURNING id
`

type UpsertPersonParams struct {
	Source     string `json:"source"`
	ExternalID string `json:"external_id"`
	Name       string `json:"name"`
	NativeName string `json:"native_name"`
	Image      string `json:"image"`
}

func (q *Queries) UpsertPerson(ctx context.Context, arg UpsertPersonParams) (int64, error) {
	row := q.db.QueryRowContext(ctx, upsertPerson,
		arg.Source,
		arg.ExternalID,
		arg.Name,
		arg.NativeName,
		arg.Image,
	)
	var id int64
	err := row.Scan(&id)
	return id, err
}
